import matplotlib.pyplot as plt  # noqa: E402
from reportlab.lib import colors  # noqa: E402
from reportlab.lib.pagesizes import A4  # noqa: E402
from reportlab.lib.styles import ParagraphStyle  # noqa: E402
from reportlab.lib.units import mm  # noqa: E402
from reportlab.pdfbase import pdfmetrics  # noqa: E402
from reportlab.pdfbase.ttfonts import TTFont  # noqa: E402
from reportlab.platypus import (Image, KeepTogether, Paragraph, SimpleDocTemplate, Spacer, Table,  # noqa: E402
                                TableStyle)

from config.rules import CLAIM_FIELDS
from config.settings import settings
from models import db
from services import mandi, satellite, weather
from tools.climate import ndvi_change
from tools.events import countdown, observed_for_plot
from tools.ledger import season_entries, season_metrics
from tools.money import d, inr, money

DISCLAIMER = ("This document is a supporting record prepared by the farmer using CropTrail. Claim eligibility, "
              "assessment and settlement are decided only by the official crop insurance scheme and its insurer.")
SECTION_TITLES = [
    "1. CropTrail loss evidence record", "2. Farmer, plot and crop", "3. Loss event", "4. Season ledger",
    "5. Area weather evidence", "6. Satellite crop health", "7. Photo timeline", "8. Estimated loss",
    "9. Data sources", "10. Disclaimer",
]
EVENT_LABELS = {"hail": "Hail", "inundation": "Inundation / waterlogging", "cloudburst": "Cloudburst",
                "landslide": "Landslide", "natural_fire": "Natural fire",
                "unseasonal_rain_post_harvest": "Unseasonal rain after harvest", "other": "Other"}

_fonts_ready = False


def _fonts():
    global _fonts_ready
    if _fonts_ready:
        return
    base = Path("/usr/share/fonts/truetype/dejavu")
    for name, file in (("DV", "DejaVuSans.ttf"), ("DV-Bold", "DejaVuSans-Bold.ttf")):
        candidates = [base / file, Path(matplotlib.get_data_path()) / "fonts" / "ttf" / file]
        for c in candidates:
            if c.exists():
                pdfmetrics.registerFont(TTFont(name, str(c)))
                break
    _fonts_ready = True


def _styles():
    _fonts()
    body = ParagraphStyle("body", fontName="DV", fontSize=9, leading=12)
    return {
        "title": ParagraphStyle("title", fontName="DV-Bold", fontSize=16, leading=20, textColor=colors.HexColor("#1F7A4D")),
        "h": ParagraphStyle("h", fontName="DV-Bold", fontSize=11.5, leading=15, spaceBefore=10, spaceAfter=4,
                            textColor=colors.HexColor("#1F7A4D")),
        "body": body,
        "small": ParagraphStyle("small", parent=body, fontSize=7.5, leading=10, textColor=colors.HexColor("#555555")),
        "warn": ParagraphStyle("warn", parent=body, textColor=colors.HexColor("#B3261E"), fontName="DV-Bold"),
    }


def _table(data, widths, header=True):
    st = _styles()
    cell = ParagraphStyle("cell", parent=st["body"], fontSize=8.5, leading=11)
    head = ParagraphStyle("head", parent=cell, fontName="DV-Bold")
    data = [[Paragraph(escape(str(c)), head if header and r == 0 else cell) if isinstance(c, str) else c for c in row]
            for r, row in enumerate(data)]
    t = Table(data, colWidths=widths, repeatRows=1 if header else 0)
    style = [("FONT", (0, 0), (-1, -1), "DV", 8.5), ("VALIGN", (0, 0), (-1, -1), "TOP"),
             ("GRID", (0, 0), (-1, -1), 0.3, colors.HexColor("#CCCCCC")),
             ("BOTTOMPADDING", (0, 0), (-1, -1), 3), ("TOPPADDING", (0, 0), (-1, -1), 3)]
    if header:
        style += [("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8F2EC")), ("FONT", (0, 0), (-1, 0), "DV-Bold", 8.5)]
    t.setStyle(TableStyle(style))
    return t


def _kv(rows):
    return _table([[k, v if v not in (None, "") else "Not entered"] for k, v in rows], [55 * mm, 115 * mm], header=False)


def _rain_chart(days: list[dict], normal: float | None, event_date: str) -> io.BytesIO:
    fig, ax = plt.subplots(figsize=(6.2, 2.3), dpi=150)
    labels = [datetime.fromisoformat(x["date"]).strftime("%d %b") for x in days]
    vals = [x["precipitation_sum"] or 0 for x in days]
    cols = ["#1F7A4D" if x["date"] != event_date else "#B3261E" for x in days]
    bars = ax.bar(labels, vals, color=cols)
    for b, x in zip(bars, days):
        if x.get("simulated"):
            b.set_hatch("//")
        if x["precipitation_sum"] is None:
            ax.text(b.get_x() + b.get_width() / 2, 0.5, "n/a", ha="center", fontsize=7)
    if normal is not None:
        ax.axhline(normal, color="#C77700", linestyle="--", linewidth=1.2, label=f"1991-2020 monthly avg ({normal:g} mm/day)")
        ax.legend(fontsize=7, loc="upper right", frameon=False)
    ax.set_ylabel("Rain (mm/day)", fontsize=8)
    ax.tick_params(labelsize=7)
    for s in ("top", "right"):
        ax.spines[s].set_visible(False)
    fig.tight_layout()
    buf = io.BytesIO()
    fig.savefig(buf, format="png")
    plt.close(fig)
    buf.seek(0)
    return buf


def _footer(canvas, doc):
    canvas.saveState()
    canvas.setFont("DV", 7.5)
    canvas.setFillColor(colors.HexColor("#777777"))
    canvas.drawString(15 * mm, 10 * mm, "CropTrail evidence record · supporting document only")
    canvas.drawRightString(195 * mm, 10 * mm, f"Page {doc.page}")
    canvas.restoreState()


def gather(conn, event_id: str) -> dict:
    """Collect every value the pack shows. Failures become 'Not available' sections, never exceptions."""
    ev = db.one(conn, "SELECT * FROM event WHERE event_id = ?", (event_id,))
    plot = db.one(conn, "SELECT * FROM plot WHERE plot_id = ?", (ev["plot_id"],))
    farmer = db.one(conn, "SELECT * FROM farmer WHERE farmer_id = ?", (plot["farmer_id"],))
    season = db.one(conn, "SELECT * FROM season WHERE season_id = ?", (ev["season_id"],)) if ev["season_id"] else None
    ev_date = date.fromisoformat(ev["event_date"])
    sources, out = [], {"event": ev, "plot": plot, "farmer": farmer, "season": season}
    now = settings.now().isoformat()

    out["entries"] = season_entries(conn, season["season_id"]) if season else []
    out["metrics"] = season_metrics(conn, season["season_id"]) if season else None

    try:
        obs = observed_for_plot(conn, plot, ev_date - timedelta(days=3), ev_date + timedelta(days=2))
        normal = weather.get_monthly_normal(plot["lat"], plot["lon"], ev_date.month)
        out["weather"] = {"days": obs["days"], "normal": normal["mean_daily_precip_mm"],
                          "fixture_kind": obs.get("fixture_kind"), "source": obs["source"]}
        sources.append({"name": "Area weather (Open-Meteo)", "mode": obs["mode"], "fetched_at": obs["fetched_at"],
                        "fixture_kind": obs.get("fixture_kind")})
        sources.append({"name": "1991-2020 rainfall normals (Open-Meteo archive)", "mode": normal["mode"],
                        "fetched_at": now, "fixture_kind": normal.get("fixture_kind")})
    except weather.DataUnavailable as exc:
        out["weather"] = {"error": exc.message}
        sources.append({"name": "Area weather (Open-Meteo)", "mode": "failed", "fetched_at": now})

    sat = satellite.get_images(plot, ev_date - timedelta(days=25), ev_date + timedelta(days=25))
    if sat is None:
        out["ndvi"] = {"error": "Satellite data not available for this plot."}
        sources.append({"name": "Sentinel-2 NDVI", "mode": "failed", "fetched_at": now})
    else:
        harvests = [e["entry_date"] for e in out["entries"] if e["category"] == "harvest"]
        out["ndvi"] = {**ndvi_change(sat["images"], ev_date, harvests), "fixture_kind": sat.get("fixture_kind"),
                       "source": sat["source"]}
        sources.append({"name": "Sentinel-2 NDVI", "mode": sat["mode"], "fetched_at": now,
                        "fixture_kind": sat.get("fixture_kind")})

    out["photos"] = db.rows(conn, "SELECT * FROM photo WHERE event_id = ? OR (season_id = ? AND taken_at >= ?) "
                                  "ORDER BY taken_at",
                            (event_id, ev["season_id"] or "", (ev_date - timedelta(days=1)).isoformat()))
    price = mandi.get_price(season["crop"], plot["nearest_market"]) if season else None
    out["price"] = price
    if price:
        sources.append({"name": f"Mandi price ({price['source']})", "mode": price["mode"], "fetched_at": now})
    out["sources"] = sources
    out["countdown"] = countdown(ev)
    return out


def build_pdf(data: dict, path: Path) -> None:
    st = _styles()
    ev, plot, farmer, season = data["event"], data["plot"], data["farmer"], data["season"]
    story = []
    P = lambda text, s="body": Paragraph(text, st[s])  # noqa: E731

    story += [P(SECTION_TITLES[0], "title"),
              P(f"Generated {settings.now().strftime('%d %b %Y, %H:%M')} IST · Pack ID {data['pack_id']}", "small")]
    if ev.get("trigger") == "demo_seed":
        story += [Spacer(1, 4), P(
            "DEMO SCENARIO ONLY: the farmer, plot, ledger records, event, loss estimate and placeholder photos are "
            "fictional. This document is not evidence of real crop damage and must not be submitted as a claim.",
            "warn")]
    if data["countdown"]["past_deadline"]:
        story += [Spacer(1, 4), P("Reporting window passed. You can still generate the record, but contact your "
                                  "insurer or agriculture office directly.", "warn")]

    story.append(P(SECTION_TITLES[1], "h"))
    story.append(_kv([
        ("Farmer", farmer["name"]), ("Village / District / State",
                                     f"{farmer.get('village') or '-'}, {farmer['district']}, {farmer['state']}"),
        ("Plot", plot["name"]), ("Survey (khasra) number", plot.get("survey_number")),
        ("Area", f"{plot['area_acres']:g} acres"), ("Pin location", f"{plot['lat']:.4f}, {plot['lon']:.4f}"),
        ("Crop and season", f"{season['crop'].title()} · {season['season_label']}" if season else None),
        ("Sowing / transplanting date", season["sowing_date"] if season else None),
        ("Insurance application / policy number", season.get("policy_number") if season else None),
    ]))

    story.append(P(SECTION_TITLES[2], "h"))
    deadline = datetime.fromisoformat(ev["report_deadline"])
    story.append(_kv([
        ("Event type", EVENT_LABELS.get(ev["type"], ev["type"])), ("Event date", ev["event_date"]),
        ("How it was detected", ev["trigger_detail"]),
        ("Confirmed by farmer", datetime.fromisoformat(ev["confirmed_at"]).strftime("%d %b %Y, %H:%M")
         if ev["confirmed_at"] else None),
        ("Reporting deadline", f"{deadline.strftime('%d %b %Y, %H:%M')} IST ({settings.report_window_hours} h window, "
                               "verify with the official scheme)"),
        ("Farmer's notes", ev.get("farmer_notes")),
    ]))

    story.append(P(SECTION_TITLES[3], "h"))
    rows = [["Date", "Category", "Item", "Qty", "Cost"]]
    for e in data["entries"]:
        qty = "" if e["quantity"] is None else f"{e['quantity']:g} {e['unit'] if e['unit'] != 'none' else ''}".strip()
        cost = "" if e["cost_inr"] is None else inr(e["cost_inr"])
        rows.append([e["entry_date"], e["category"].replace("_", " "), e["item"] or "", qty, cost])
    if len(rows) == 1:
        rows.append(["Not available", "No ledger entries for this season", "", "", ""])
    story.append(_table(rows, [24 * mm, 26 * mm, 62 * mm, 26 * mm, 32 * mm]))
    if data["metrics"]:
        story.append(Spacer(1, 3))
        story.append(P(f"<b>Total cost to date: {inr(data['metrics']['total_cost'])}</b> "
                       f"(from {data['metrics']['entry_count']} farmer-entered records)"))

    story.append(P(SECTION_TITLES[4], "h"))
    w = data["weather"]
    if "error" in w:
        story.append(P(f"Not available: {w['error']}"))
    else:
        story.append(P("Area weather (gridded model data, several km resolution), source: Open-Meteo.", "small"))
        if w.get("fixture_kind") == "synthetic":
            story.append(P("SAMPLE FIXTURE DATA (synthetic, offline demo mode) - not observed weather. "
                           "Capture real data before using this record.", "warn"))
        if any(x.get("simulated") for x in w["days"]):
            story.append(P("Hatched bars are SIMULATED values entered for a demo, not observations.", "warn"))
        wrows = [["Date", "Rain (mm)", "Max temp (°C)", "Note"]]
        for x in w["days"]:
            note = "Event day" if x["date"] == ev["event_date"] else ""
            if x.get("simulated"):
                note = (note + " · simulated").strip(" ·")
            wrows.append([x["date"], "n/a" if x["precipitation_sum"] is None else f"{x['precipitation_sum']:g}",
                          "n/a" if x["temperature_2m_max"] is None else f"{x['temperature_2m_max']:g}", note])
        story.append(_table(wrows, [35 * mm, 30 * mm, 35 * mm, 70 * mm]))
        story.append(P(f"1991-2020 average daily rainfall for {date.fromisoformat(ev['event_date']).strftime('%B')}: "
                       f"{w['normal']:g} mm/day.", "small"))
        story.append(Image(_rain_chart(w["days"], w["normal"], ev["event_date"]), width=165 * mm, height=61 * mm))

    story.append(P(SECTION_TITLES[5], "h"))
    n = data["ndvi"]
    if "error" in n:
        story.append(P(f"Not available: {n['error']}"))
    else:
        if n.get("fixture_kind") == "synthetic":
            story.append(P("SAMPLE FIXTURE DATA (synthetic) - not real satellite measurements.", "warn"))
        fmt = lambda v: "No clear satellite image for this period (clouds)" if v is None else f"{v:.2f}"  # noqa: E731
        story.append(_kv([
            ("NDVI before event", f"{fmt(n['ndvi_before'])}" + (f" (image {n['before_date']})" if n["before_date"] else "")),
            ("NDVI after event", f"{fmt(n['ndvi_after'])}" + (f" (image {n['after_date']})" if n["after_date"] else "")),
            ("Change", "Not available" if n["ndvi_change_pct"] is None else f"{n['ndvi_change_pct']:+.1f}%"),
            ("Source", f"{n['source']}, median NDVI over a circle matching the plot area, clouds masked"),
        ]))
        for note in n["notes"]:
            story.append(P(f"Note: {note}", "small"))
        story.append(P("Satellite data is supporting context only, not proof of loss.", "small"))

    story.append(P(SECTION_TITLES[6], "h"))
    photos = data["photos"]
    if not photos:
        story.append(P("Not available: no photos attached to this event."))
    else:
        cells, row = [], []
        for ph in photos:
            caption = (f"{datetime.fromisoformat(ph['taken_at']).strftime('%d %b %Y %H:%M')}<br/>"
                       f"{'%.4f, %.4f' % (ph['lat'], ph['lon']) if ph['lat'] is not None else 'location unknown'}"
                       f" ({ph['location_source']})")
            if ph.get("vision_tag"):
                caption += f"<br/>AI hint, not a diagnosis: {ph['vision_tag'].replace('_', ' ')}"
            if ph.get("is_placeholder"):
                caption += "<br/><b>Demo placeholder image</b>"
            try:
                img = Image(ph["file_path"], width=52 * mm, height=39 * mm)
            except Exception:
                img = P("Image file missing")
            row.append([img, P(caption, "small")])
            if len(row) == 3:
                cells.append(row)
                row = []
        if row:
            cells.append(row + [[""]] * (3 - len(row)))
        t = Table(cells, colWidths=[57 * mm] * 3)
        t.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "TOP")]))
        story.append(t)

    story.append(P(SECTION_TITLES[7], "h"))
    q = ev.get("estimated_loss_quintals")
    price = data["price"]
    if q is None:
        story.append(P("Not available: the farmer has not entered an estimated loss."))
    elif not price:
        story.append(P(f"Farmer's estimate: {q:g} quintals. Value not available (no mandi price)."))
    else:
        value = money(d(q) * d(price["modal_price"]))
        story.append(_kv([
            ("Farmer's estimate", f"{q:g} quintals × {inr(price['modal_price'])}/quintal = {inr(value, True)}"),
            ("Price used", f"Modal price at {price['market']} on {price['arrival_date']} ({price['source']}, "
                           f"{price['mode']})"),
        ]))
        data["estimated_value"] = value
        story.append(P("This is the farmer's own estimate, not an assessment.", "small"))

    story.append(P(SECTION_TITLES[8], "h"))
    srows = [["Source", "Mode", "Fetched at"]]
    for s in data["sources"]:
        mode = s["mode"] + (" (synthetic fixture)" if s.get("fixture_kind") == "synthetic" else "")
        srows.append([s["name"], mode, s["fetched_at"][:16].replace("T", " ")])
    srows.append(["Ledger, photos, loss estimate", "farmer-entered", "-"])
    story.append(_table(srows, [85 * mm, 55 * mm, 40 * mm]))
    story.append(Spacer(1, 4))
    story.append(P("Fields typically asked for when intimating a crop loss (check against the official "
                   "scheme form): " + "; ".join(CLAIM_FIELDS) + ".", "small"))

    story.append(KeepTogether([P(SECTION_TITLES[9], "h"), P(DISCLAIMER)]))

    doc = SimpleDocTemplate(str(path), pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm,
                            topMargin=14 * mm, bottomMargin=16 * mm, title="CropTrail evidence record",
                            author="CropTrail")
    doc.build(story, onFirstPage=_footer, onLaterPages=_footer)


def generate(conn, event_id: str) -> dict:
    data = gather(conn, event_id)
    pack_id = db.new_id("PK")
    data["pack_id"] = pack_id
    out_dir = settings.upload_dir / "packs"
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / f"{pack_id}.pdf"
    build_pdf(data, path)
    record = {"pack_id": pack_id, "event_id": event_id, "generated_at": settings.now().isoformat(),
              "file_path": str(path), "data_sources": db.dumps(data["sources"]),
              "past_deadline": int(data["countdown"]["past_deadline"])}
    db.insert(conn, "evidence_pack", record)
    return {"pack_id": pack_id, "file_url": f"/api/evidence-packs/{pack_id}/file", "data_sources": data["sources"],
            "past_deadline": data["countdown"]["past_deadline"], "estimated_value": data.get("estimated_value"),
            "generated_at": record["generated_at"]}
